      { "@type": "ListItem", "position": 2, "item": { "@type": "TouristAttraction", "name": "Day 2: Ourika Valley Excursion", "description": "Round-trip excursion (~84 km) to the Ourika Valley in the Atlas Mountains foothills, including Berber villages and an argan oil cooperative." } },
