      { "@type": "ListItem", "position": 5, "item": { "@type": "TouristAttraction", "name": "Day 5: Marrakech to Dades Gorges", "description": "Cross the High Atlas via Ait Benhaddou to the Dades Valley, overnight in a kasbah-style guesthouse." } },
